*******************************************************************************
* v3copy.asm -- video3's copy engine on the host emulator.  GENERATED by
* bench/mkv3copy.py; edit the generator.
*
*   sh video3/bench/run-v3copy.sh
*
* plan 6.  Bitmap mode makes VRAM observable: a byte IS a palette index IS a
* pixel, so a copy that puts a byte in the wrong place is visible.  The list
* covers aligned and unaligned columns, both directions in both axes, and four
* overlapping copies - which is where a direction bit that walks the wrong way
* destroys its own source.
*******************************************************************************

VCTRL   EQU     $FF60
VSCROLL EQU     $FF61
WPTR0   EQU     $FF68
WPTR1   EQU     $FF69
WPTR2   EQU     $FF6A
WADV    EQU     $FF6B
VDATA   EQU     $FF6C
VSTAT   EQU     $FF6D
PIDXL   EQU     $FF6E
PIDXH   EQU     $FF6F
PDATL   EQU     $FF70
PDATH   EQU     $FF71
CPTR0   EQU     $FF72
CPTR1   EQU     $FF73
CPTR2   EQU     $FF74
CWIDTH  EQU     $FF75
CHEIGHT EQU     $FF76
CCTRL   EQU     $FF77
SIMPORT EQU     $FF2F

row     EQU     $C100
seed    EQU     $C102

        ORG     $8000
        FCC     "6309"
        JMP     start

        SETDP   $FF
start   orcc    #$50
        lds     #$E000
        lda     #$FF
        tfr     a,dp
        clr     <VCTRL          display off, bitmap, WMODE 00
        clr     <WADV
        clr     <VSCROLL
        clr     <VSCROLL+1

* --- sub-palette 0: entry i = i * $0101, so a pixel's value is recoverable
        clr     <PIDXH
        clr     <PIDXL
        clrb
pal1    stb     <PDATL
        stb     <PDATH
        incb
        bne     pal1

* --- the pattern: VRAM[r][c] = (r * 7 + c * 3) & $FF
        clr     row
        clr     row+1
fr1     ldd     row
        lslb
        rola
        lslb
        rola                    D = row * 4 -> WPTR1:WPTR0 is row * 1024
        clr     <WPTR0
        stb     <WPTR1
        sta     <WPTR2          WPTR = row * 1024, so the row starts at WPTR1
        ldb     row+1
        lda     #7
        mul                     B = row * 7, low byte
        stb     seed
        ldy     #640
fc1     lda     seed
        sta     <VDATA
        adda    #3
        sta     seed
        leay    -1,y
        bne     fc1
        ldd     row
        addd    #1
        std     row
        cmpd    #200
        blo     fr1

* --- the copies
* vertical only, non-overlapping
        lda     #$00
        sta     <CPTR2
        lda     #$00
        sta     <CPTR1
        lda     #$00
        sta     <CPTR0
        lda     #$01
        sta     <WPTR2
        lda     #$90
        sta     <WPTR1
        lda     #$00
        sta     <WPTR0
        lda     #$40
        sta     <CWIDTH
        lda     #$10
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw00    lda     <VSTAT
        bmi     cw00
* horizontal, columns congruent mod 4
        lda     #$00
        sta     <CPTR2
        lda     #$50
        sta     <CPTR1
        lda     #$00
        sta     <CPTR0
        lda     #$00
        sta     <WPTR2
        lda     #$70
        sta     <WPTR1
        lda     #$40
        sta     <WPTR0
        lda     #$20
        sta     <CWIDTH
        lda     #$08
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw01    lda     <VSTAT
        bmi     cw01
* horizontal, NOT congruent mod 4
        lda     #$00
        sta     <CPTR2
        lda     #$A0
        sta     <CPTR1
        lda     #$01
        sta     <CPTR0
        lda     #$00
        sta     <WPTR2
        lda     #$C0
        sta     <WPTR1
        lda     #$42
        sta     <WPTR0
        lda     #$21
        sta     <CWIDTH
        lda     #$08
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw02    lda     <VSTAT
        bmi     cw02
* overlapping scroll UP, rows ascend
        lda     #$00
        sta     <CPTR2
        lda     #$F0
        sta     <CPTR1
        lda     #$00
        sta     <CPTR0
        lda     #$00
        sta     <WPTR2
        lda     #$D0
        sta     <WPTR1
        lda     #$00
        sta     <WPTR0
        lda     #$80
        sta     <CWIDTH
        lda     #$20
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw03    lda     <VSTAT
        bmi     cw03
* overlapping scroll DOWN, rows descend
        lda     #$01
        sta     <CPTR2
        lda     #$E0
        sta     <CPTR1
        lda     #$00
        sta     <CPTR0
        lda     #$02
        sta     <WPTR2
        lda     #$00
        sta     <WPTR1
        lda     #$00
        sta     <WPTR0
        lda     #$80
        sta     <CWIDTH
        lda     #$20
        sta     <CHEIGHT
        lda     #$03
        sta     <CCTRL          GO
cw04    lda     <VSTAT
        bmi     cw04
* overlapping RIGHT, columns descend
        lda     #$02
        sta     <CPTR2
        lda     #$80
        sta     <CPTR1
        lda     #$00
        sta     <CPTR0
        lda     #$02
        sta     <WPTR2
        lda     #$80
        sta     <WPTR1
        lda     #$08
        sta     <WPTR0
        lda     #$40
        sta     <CWIDTH
        lda     #$08
        sta     <CHEIGHT
        lda     #$05
        sta     <CCTRL          GO
cw05    lda     <VSTAT
        bmi     cw05
* overlapping LEFT, columns ascend
        lda     #$02
        sta     <CPTR2
        lda     #$D0
        sta     <CPTR1
        lda     #$08
        sta     <CPTR0
        lda     #$02
        sta     <WPTR2
        lda     #$D0
        sta     <WPTR1
        lda     #$00
        sta     <WPTR0
        lda     #$40
        sta     <CWIDTH
        lda     #$08
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw06    lda     <VSTAT
        bmi     cw06
* one row, one byte
        lda     #$01
        sta     <CPTR2
        lda     #$8E
        sta     <CPTR1
        lda     #$7F
        sta     <CPTR0
        lda     #$01
        sta     <WPTR2
        lda     #$89
        sta     <WPTR1
        lda     #$40
        sta     <WPTR0
        lda     #$01
        sta     <CWIDTH
        lda     #$01
        sta     <CHEIGHT
        lda     #$01
        sta     <CCTRL          GO
cw07    lda     <VSTAT
        bmi     cw07

* --- bitmap mode, 640x200, display on
        lda     #$80            b7 display, MODE 00 bitmap, VMODE 00
        sta     <VCTRL
        lda     #$A0
        sta     SIMPORT
done    bra     done
        END
